trace_round.go.src:
package main

import (
	"fmt"
	"math"
)

func main() {
	a, b := 2.5, -2.5
	fmt.Println("Floor", math.Floor(a), math.Floor(b))
	fmt.Println("Ceil", math.Ceil(a), math.Ceil(b))
	fmt.Println("Round", math.Round(a), math.Round(b))
	fmt.Println("Trunc", math.Trunc(a), math.Trunc(b))
}

